-- Generated by scripts/assign_frequency_rank.py
-- Sets vocabulary.frequency_rank (1 = most frequent English word).
-- Self-contained, re-runnable migration: adds the column, indexes it,
-- then ranks every term (matched on LOWER(term)).

ALTER TABLE vocabulary ADD COLUMN IF NOT EXISTS frequency_rank INT;
CREATE INDEX IF NOT EXISTS idx_vocabulary_frequency_rank ON vocabulary (frequency_rank);

